"use client";

import { FC } from "react";
import { Bar, BarChart, CartesianGrid, Legend, Line, LineChart, XAxis, YAxis } from "recharts";
import { ChartContainer, ChartTooltip, ChartTooltipContent, ChartConfig } from "@/components/ui/chart";
import type { SerializableChart } from "./schema";
import { cn } from "@/lib/utils";

interface ChartProps extends SerializableChart {
  className?: string;
  onDataPointClick?: (dataPoint: any) => void;
}

export const Chart: FC<ChartProps> = ({
  id,
  type,
  title,
  description,
  data,
  xKey,
  series,
  showLegend = true,
  showGrid = true,
  className,
  onDataPointClick,
}) => {
  // Build ChartConfig from series
  const chartConfig: ChartConfig = series.reduce((config, s) => {
    config[s.key] = {
      label: s.label,
      color: s.color,
    };
    return config;
  }, {} as ChartConfig);

  // Default colors for series without explicit colors
  const defaultColors = [
    "hsl(var(--chart-1))",
    "hsl(var(--chart-2))",
    "hsl(var(--chart-3))",
    "hsl(var(--chart-4))",
    "hsl(var(--chart-5))",
  ];

  return (
    <div
      className={cn("flex flex-col gap-2", className)}
      data-tool-ui-id={id}
      data-slot="chart"
    >
      {(title || description) && (
        <div className="space-y-1">
          {title && <h3 className="text-lg font-semibold">{title}</h3>}
          {description && <p className="text-sm text-muted-foreground">{description}</p>}
        </div>
      )}

      <ChartContainer id={id} config={chartConfig}>
        {type === "bar" ? (
          <BarChart data={data} onClick={onDataPointClick}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" vertical={false} />}
            <XAxis
              dataKey={xKey}
              tickLine={false}
              tickMargin={10}
              axisLine={false}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => {
                if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
                if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
                return value.toString();
              }}
            />
            <ChartTooltip content={<ChartTooltipContent />} />
            {showLegend && <Legend />}
            {series.map((s, index) => (
              <Bar
                key={s.key}
                dataKey={s.key}
                fill={s.color || defaultColors[index % defaultColors.length]}
                radius={[4, 4, 0, 0]}
              />
            ))}
          </BarChart>
        ) : (
          <LineChart data={data} onClick={onDataPointClick}>
            {showGrid && <CartesianGrid strokeDasharray="3 3" vertical={false} />}
            <XAxis
              dataKey={xKey}
              tickLine={false}
              tickMargin={10}
              axisLine={false}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              tickFormatter={(value) => {
                if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
                if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
                return value.toString();
              }}
            />
            <ChartTooltip content={<ChartTooltipContent />} />
            {showLegend && <Legend />}
            {series.map((s, index) => (
              <Line
                key={s.key}
                type="monotone"
                dataKey={s.key}
                stroke={s.color || defaultColors[index % defaultColors.length]}
                strokeWidth={2}
                dot={{ r: 3 }}
                activeDot={{ r: 5 }}
              />
            ))}
          </LineChart>
        )}
      </ChartContainer>
    </div>
  );
};

export { Chart } from "./chart";
export { parseSerializableChart } from "./schema";
export type { SerializableChart, ChartSeries } from "./schema";

export interface ChartSeries {
  key: string;
  label: string;
  color?: string;
}

export interface SerializableChart {
  id: string;
  type: "bar" | "line";
  title?: string;
  description?: string;
  data: Record<string, any>[];
  xKey: string;
  series: ChartSeries[];
  showLegend?: boolean;
  showGrid?: boolean;
}

export function parseSerializableChart(data: any): SerializableChart {
  // Check if data is in the dataSeries format with x/y objects
  if (data.dataSeries?.[0]?.data?.[0]?.x !== undefined) {
    // Transform dataSeries[].data[{x,y}] format to expected format
    const firstSeries = data.dataSeries[0];
    const xValues = firstSeries.data.map((point: any) => point.x);
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.dataSeries.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index]?.y;
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.dataSeries.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with xAxis.categories and series[].data
  if (data.xAxis?.categories && data.series?.[0]?.data) {
    // Transform xAxis.categories + series[].data format to expected format
    const xValues = data.xAxis.categories || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with xAxis.values and series[].values (camelCase)
  if (data.xAxis?.values && data.series?.[0]?.values) {
    // Transform xAxis.values + series[].values format to expected format
    const xValues = data.xAxis.values || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.values?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the alternative format with x_axis/y_axis/series.values (snake_case)
  if (data.x_axis && data.series?.[0]?.values) {
    // Transform alternative format to expected format
    const xValues = data.x_axis.values || [];
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.values?.[index];
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || "bar",
      title: data.title,
      description: data.description,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Check if data is in the series[].data[{x, y}] format (similar to dataSeries but uses 'series')
  if (data.series?.[0]?.data?.[0]?.x !== undefined) {
    // Transform series[].data[{x,y}] format to expected format
    const firstSeries = data.series[0];
    const xValues = firstSeries.data.map((point: any) => point.x);
    const transformedData: Record<string, any>[] = xValues.map((xVal: any, index: number) => {
      const row: Record<string, any> = { x: xVal };
      data.series.forEach((s: any, seriesIndex: number) => {
        const key = `series${seriesIndex}`;
        row[key] = s.data?.[index]?.y;
      });
      return row;
    });

    const transformedSeries: ChartSeries[] = data.series.map((s: any, index: number) => ({
      key: `series${index}`,
      label: s.name || s.label || `Series ${index + 1}`,
      color: s.color,
    }));

    return {
      id: data.id || crypto.randomUUID(),
      type: data.type || data.series?.[0]?.type || "bar",
      title: data.title || data.xAxisTitle,
      description: data.description || data.yAxisTitle,
      data: transformedData,
      xKey: "x",
      series: transformedSeries,
      showLegend: data.showLegend ?? true,
      showGrid: data.showGrid ?? true,
    };
  }

  // Standard format
  return {
    id: data.id || crypto.randomUUID(),
    type: data.type || "bar",
    title: data.title,
    description: data.description,
    data: data.data || [],
    xKey: data.xKey || "x",
    series: data.series || [],
    showLegend: data.showLegend ?? true,
    showGrid: data.showGrid ?? true,
  };
}

"use client";

import { FC } from "react";
import { cn } from "@/lib/utils";
import * as LucideIcons from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { Chart } from "@/components/tool-ui/chart";
import type { SerializableDashboard, MetricTile, ChartTile, StatComparisonTile, ProgressTile } from "./schema";

interface DashboardProps extends SerializableDashboard {
  className?: string;
}

// Get tile size class for flex layout (tiles auto-fill available space)
const getTileSizeClass = (size: string = "small", columns: number = 2) => {
  switch (size) {
    case "large":
      // Large tiles take full width
      return "w-full";
    case "medium":
      // Medium tiles flex to fill space
      if (columns === 1) return "w-full";
      return "flex-1 min-w-full md:min-w-[300px]";
    case "small":
    default:
      // Small tiles flex to fill space
      if (columns === 1) return "w-full";
      return "flex-1 min-w-full md:min-w-[200px]";
  }
};

// Metric Tile Component
const MetricTileComponent: FC<{ tile: MetricTile; columns: number }> = ({ tile, columns }) => {
  const trendIcon = tile.trend === "up"
    ? <LucideIcons.TrendingUp className="w-3 h-3" />
    : tile.trend === "down"
    ? <LucideIcons.TrendingDown className="w-3 h-3" />
    : <LucideIcons.Minus className="w-3 h-3" />;

  const trendColor = tile.trend === "up"
    ? "text-green-600 dark:text-green-400"
    : tile.trend === "down"
    ? "text-red-600 dark:text-red-400"
    : "text-muted-foreground";

  const Icon = tile.icon ? (LucideIcons as any)[tile.icon] : null;

  return (
    <div
      className={cn(
        getTileSizeClass(tile.size, columns),
        "rounded-3xl px-5 py-5 transition-all duration-300 hover:brightness-95"
      )}
      style={{ backgroundColor: '#EFF2F5' }}
    >
      <div className="flex flex-col gap-2">
        {Icon && (
          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white dark:bg-black mb-1">
            <Icon className="h-5 w-5 text-black dark:text-white" />
          </div>
        )}
        <div className="space-y-0.5">
          <p className="text-xs font-medium text-muted-foreground">
            {tile.label}
          </p>
          <div className="flex items-baseline gap-1.5">
            <p className="text-md font-bold tracking-tight">
              {tile.value}
            </p>
            {tile.delta && tile.trend && (
              <div className={cn("flex items-center gap-0.5 text-xs font-medium", trendColor)}>
                {trendIcon}
                <span>{tile.delta}</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// Chart Tile Component
const ChartTileComponent: FC<{ tile: ChartTile; columns: number }> = ({ tile, columns }) => {
  return (
    <div
      className={cn(
        getTileSizeClass(tile.size, columns),
        "rounded-3xl px-5 py-5 transition-all duration-300 hover:brightness-95"
      )}
      style={{ backgroundColor: '#EFF2F5' }}
    >
      <Chart {...tile.chart} />
    </div>
  );
};

// Stat Comparison Tile Component
const StatComparisonTileComponent: FC<{ tile: StatComparisonTile; columns: number }> = ({ tile, columns }) => {
  return (
    <div
      className={cn(
        getTileSizeClass(tile.size, columns),
        "rounded-3xl px-5 py-5 transition-all duration-300 hover:brightness-95"
      )}
      style={{ backgroundColor: '#EFF2F5' }}
    >
      <div className="flex flex-col gap-3">
        <p className="text-xs font-semibold text-muted-foreground">
          {tile.label}
        </p>
        <div className="flex items-center justify-around gap-3">
          {tile.stats.map((stat, index) => (
            <div key={index} className="flex flex-col items-center gap-0.5">
              <p className="text-[10px] text-muted-foreground">{stat.label}</p>
              <p className="text font-bold">{stat.value}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

// Progress Tile Component
const ProgressTileComponent: FC<{ tile: ProgressTile; columns: number }> = ({ tile, columns }) => {
  const percentage = tile.percentage ?? (tile.max > 0 ? (tile.value / tile.max) * 100 : 0);
  const showPercentage = tile.showPercentage ?? true;

  return (
    <div
      className={cn(
        getTileSizeClass(tile.size, columns),
        "rounded-3xl px-5 py-5 transition-all duration-300 hover:brightness-95"
      )}
      style={{ backgroundColor: '#EFF2F5' }}
    >
      <div className="flex flex-col gap-3">
        <div className="flex items-center justify-between">
          <p className="text-xs font-semibold text-muted-foreground">
            {tile.label}
          </p>
          {showPercentage && (
            <p className="text-xs font-bold">
              {Math.round(percentage)}%
            </p>
          )}
        </div>
        <Progress value={percentage} className="h-1.5" />
        <div className="flex items-center justify-between text-[10px] text-muted-foreground">
          <span>{tile.value.toLocaleString()}</span>
          <span>{tile.max.toLocaleString()}</span>
        </div>
      </div>
    </div>
  );
};

// Main Dashboard Component
export const Dashboard: FC<DashboardProps> = ({
  id,
  title,
  description,
  tiles,
  columns = 2,
  className,
}) => {
  const flexClass = cn(
    "flex flex-wrap gap-3"
  );

  return (
    <div
      className={cn("space-y-3", className)}
      data-tool-ui-id={id}
      data-slot="dashboard"
    >
      {/* Header */}
      {(title || description) && (
        <div className="space-y-0.5">
          {title && (
            <h3 className="text-base font-semibold tracking-tight">
              {title}
            </h3>
          )}
          {description && (
            <p className="text-xs text-muted-foreground">
              {description}
            </p>
          )}
        </div>
      )}

      {/* Tiles Flex Container */}
      <div className={flexClass}>
        {tiles.map((tile) => {
          switch (tile.type) {
            case "metric":
              return <MetricTileComponent key={tile.id} tile={tile} columns={columns} />;
            case "chart":
              return <ChartTileComponent key={tile.id} tile={tile} columns={columns} />;
            case "stat-comparison":
              return <StatComparisonTileComponent key={tile.id} tile={tile} columns={columns} />;
            case "progress":
              return <ProgressTileComponent key={tile.id} tile={tile} columns={columns} />;
            default:
              return null;
          }
        })}
      </div>
    </div>
  );
};

export { Dashboard } from "./dashboard";
export {
  parseSerializableDashboard,
  type SerializableDashboard,
  type DashboardTile,
  type MetricTile,
  type ChartTile,
  type StatComparisonTile,
  type ProgressTile,
} from "./schema";

import type { SerializableChart } from "../chart/schema";

// Metric/KPI tile
export interface MetricTile {
  type: "metric";
  id: string;
  label: string;
  value: string | number;
  icon?: string;
  trend?: "up" | "down" | "neutral";
  delta?: string;
  size?: "small" | "medium" | "large";
}

// Chart tile (reuses existing Chart component)
export interface ChartTile {
  type: "chart";
  id: string;
  chart: SerializableChart;
  size?: "small" | "medium" | "large";
}

// Stat comparison tile
export interface StatComparisonTile {
  type: "stat-comparison";
  id: string;
  label: string;
  stats: Array<{ label: string; value: string | number }>;
  size?: "small" | "medium" | "large";
}

// Progress tile
export interface ProgressTile {
  type: "progress";
  id: string;
  label: string;
  value: number;
  max: number;
  percentage?: number;
  showPercentage?: boolean;
  size?: "small" | "medium" | "large";
}

// Discriminated union for tile types
export type DashboardTile = MetricTile | ChartTile | StatComparisonTile | ProgressTile;

// Main dashboard interface
export interface SerializableDashboard {
  id: string;
  title?: string;
  description?: string;
  tiles: DashboardTile[];
  columns?: 1 | 2;
}

export function parseSerializableDashboard(data: any): SerializableDashboard {
  // Helper function to parse trend string to trend type
  const parseTrend = (trendStr?: string): "up" | "down" | "neutral" | undefined => {
    if (!trendStr) return undefined;
    const str = trendStr.toLowerCase();
    if (str.includes('+') || str.includes('↑') || str.includes('positive')) return "up";
    if (str.includes('-') || str.includes('↓') || str.includes('negative')) return "down";
    return "neutral";
  };

  // Handle kpis format (alternative to tiles)
  let tilesData = data.tiles;
  if (!tilesData && data.kpis) {
    tilesData = data.kpis.map((kpi: any) => ({
      type: "metric",
      id: kpi.id || crypto.randomUUID(),
      label: kpi.label,
      value: kpi.value,
      icon: kpi.icon,
      trend: parseTrend(kpi.trend),
      delta: kpi.trend, // The trend string becomes the delta
      size: kpi.size,
    }));
  }

  // Auto-generate IDs for tiles if not provided
  const tiles = (tilesData || []).map((tile: any) => ({
    ...tile,
    id: tile.id || crypto.randomUUID(),
  }));

  // Clamp columns to max 2
  const columns = Math.min(data.columns || 2, 2) as 1 | 2;

  return {
    id: data.id || crypto.randomUUID(),
    title: data.title,
    description: data.description,
    tiles,
    columns,
  };
}
